//! The result document's types for the TypeScript and Python helpers of
//! `test-support/` that write `journey` documents (ADR 0063): the bundle's
//! `documents.result_document` and every type it reaches, generated by the
//! same outside generators as the SDK layers into each package's
//! `generated/` folder.

use std::collections::BTreeMap;

use anyhow::{Context as _, Result};
use serde_json::{Map, Value};

use super::{External, Generator, json_text, projection};

/// `@goodfetch/test-support`'s generated folder.
pub(super) const TYPESCRIPT_FOLDER: &str = "test-support/typescript/src/generated";

/// `goodfetch-test-support`'s generated package.
pub(super) const PYTHON_FOLDER: &str = "test-support/python/src/goodfetch_test_support/generated";

/// The generators' input file name, which `datamodel-code-generator` writes
/// into its header.
const INPUT_NAME: &str = "result-document.json";

/// What every file says first.
const NOTICE: &str = "Generated by `xtask codegen` from the bundle; never edit by hand.";

/// Adds the generated package's `__init__.py` to `files`, and each
/// language's types file to `externals`.
pub(super) fn add(
    bundle: &Value,
    files: &mut BTreeMap<String, Vec<u8>>,
    externals: &mut Vec<External>,
) -> Result<()> {
    files.insert(
        format!("{PYTHON_FOLDER}/__init__.py"),
        format!(
            "\"\"\"The types `xtask codegen` generates for the helpers (ADR 0063).\n\n{NOTICE}\n\"\"\"\n"
        )
        .into_bytes(),
    );
    externals.push(External {
        output: format!("{PYTHON_FOLDER}/result_document.py"),
        generator: Generator::DatamodelCodegen,
        input_name: INPUT_NAME,
        input: json_text(&input(bundle, true)?)?,
        prefix: String::new(),
        header: format!("\"\"\"The result document's types (ADR 0063).\n\n{NOTICE}\n\"\"\""),
    });
    externals.push(External {
        output: format!("{TYPESCRIPT_FOLDER}/result-document.ts"),
        generator: Generator::Json2ts,
        input_name: INPUT_NAME,
        input: json_text(&input(bundle, false)?)?,
        // The notice comes first, then the generator's output, which has no
        // banner of its own.
        prefix: format!("// {NOTICE}\n\n"),
        header: String::new(),
    });
    Ok(())
}

/// The generators' input: a root that holds no value, with every type the
/// result document reaches under `$defs`. For Python the root is an empty
/// model, never `RootModel[Any]`.
fn input(bundle: &Value, python: bool) -> Result<Value> {
    let root = bundle
        .get("documents")
        .and_then(|documents| documents.get("result_document"))
        .context("the bundle's `documents` maps no `result_document`")?;
    let definitions = bundle
        .get("$defs")
        .and_then(Value::as_object)
        .context("the bundle has no `$defs`")?;
    let reached = projection::reached(root, definitions)?;
    let mut input = serde_json::json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "ResultDocumentTypes",
        "description": "The root of the result document's types, which holds no value of its own.",
        "$defs": definitions
            .iter()
            .filter(|(name, _)| reached.contains(name.as_str()))
            .map(|(name, definition)| (name.clone(), definition.clone()))
            .collect::<Map<String, Value>>(),
    });
    if python {
        input["type"] = Value::from("object");
        input["additionalProperties"] = Value::Bool(false);
    } else {
        // `json-schema-to-typescript` reads a `$ref` as draft-07 does and
        // drops its siblings, which would leave each kind of the tagged
        // `ResultDocument` only its `kind`; an `allOf` keeps both.
        if let Some(definitions) = input.get_mut("$defs") {
            refs_beside_siblings_into_all_of(definitions);
        }
    }
    Ok(input)
}

/// Moves every `$ref` that has sibling keywords other than `description`
/// into an `allOf` beside them.
fn refs_beside_siblings_into_all_of(schema: &mut Value) {
    match schema {
        Value::Object(object) => {
            if object.len() > 1
                && object
                    .keys()
                    .any(|key| key != "$ref" && key != "description")
                && let Some(reference) = object.remove("$ref")
            {
                object.insert(
                    "allOf".to_owned(),
                    Value::Array(vec![serde_json::json!({ "$ref": reference })]),
                );
            }
            object
                .values_mut()
                .for_each(refs_beside_siblings_into_all_of);
        }
        Value::Array(items) => items.iter_mut().for_each(refs_beside_siblings_into_all_of),
        _ => {}
    }
}
